-- =============================================================================
-- VMM CRM — AMC vendor seed data (1995 rows)
-- Generated from "VMM all data - July 2025 (4).xlsx"
-- Source sheets: AC AMC List, Lift vendor store, PestVendor-Store wise
-- Run AFTER docs/sql/vmm_amc_vendors.sql
-- Lift duplicate store codes (multiple lifts) are deduped by keeping first row.
-- =============================================================================

ON DUPLICATE KEY UPDATE
  `store_name`   = VALUES(`store_name`),
  `vendor_name`  = VALUES(`vendor_name`),
  `vendor_email` = VALUES(`vendor_email`),
  `vendor_phone` = VALUES(`vendor_phone`),
  `is_active`    = 1;
